// specs/logout-functionality.spec.ts
// Spec file — Logout Functionality
// Source: .github/ui/input.txt (raw-file) — "Logout Functionality"
// Generated by: ui-testcase-orchestrator
//
// Covers:
//   1. Signout terminates the session and returns the user to the login page.
//   2. After logout the browser Back button must not restore an authenticated session.
//
// NOTE (analysis finding): in the analyzed environment the SPA renders a cached shell
// when navigating back to a hash route after logout (API calls fail with 401 rather
// than a clean redirect). The back-button test below encodes the SECURITY REQUIREMENT
// from the story (login must be required); if the application does not enforce it, this
// test will fail and surface the gap — see the run report's known-issues note.
import { test, expect } from '@playwright/test';
import { LoginPage } from '../pages/login.page';
import { MultiTenantDashboardPage } from '../pages/multi-tenant-dashboard.page';
import { config } from '../config/test-config';

test.describe('Logout Functionality', () => {
  let loginPage: LoginPage;
  let dashboardPage: MultiTenantDashboardPage;

  test.beforeEach(async ({ page }) => {
    loginPage = new LoginPage(page);
    dashboardPage = new MultiTenantDashboardPage(page);

    // Authenticate and select a tenant so a full session is established before logout.
    await loginPage.goto();
    await loginPage.login(config.username, config.password);
    await dashboardPage.assertMultiTenantDialogVisible();
    await dashboardPage.clickChooseTenantDropdown();
    await dashboardPage.selectFirstTenantOption();
    await dashboardPage.assertIsDashboard();
  });

  // Source: input.txt | Scenario: Logout terminates session and redirects to login
  test('Clicking Signout terminates the session and redirects to the login page', async ({ page }) => {

    await test.step('Click Signout from the profile menu', async () => {
      console.log('▶ Click Signout from the profile menu');
      await dashboardPage.logout();
      await page.screenshot({ path: 'test-results/screenshots/logout-functionality-signout-clicked.png' });
    });

    await test.step('Confirm logout on the "Logging out" page', async () => {
      console.log('▶ Confirm logout on the "Logging out" page');
      await loginPage.confirmLogout();
      await page.screenshot({ path: 'test-results/screenshots/logout-functionality-logout-confirmed.png' });
    });

    await test.step('Verify the user is redirected to the login page', async () => {
      console.log('▶ Verify the user is redirected to the login page');
      await loginPage.assertIsLoginPage();
      await page.screenshot({ path: 'test-results/screenshots/logout-functionality-back-on-login.png' });
    });
  });

  // Source: input.txt | Scenario: Back button after logout must not restore the session
  test('After logout the browser Back button does not restore an authenticated page', async ({ page }) => {

    await test.step('Log out of the application', async () => {
      console.log('▶ Log out of the application');
      await dashboardPage.logout();
      await loginPage.confirmLogout();
      await loginPage.assertIsLoginPage();
    });

    await test.step('Press the browser Back button and verify login is still required', async () => {
      console.log('▶ Press the browser Back button and verify login is still required');
      await loginPage.navigateBack();
      // Security requirement: authenticated content must not be restored — the Sign In
      // page must be presented again.
      await loginPage.assertIsLoginPage();
      await page.screenshot({ path: 'test-results/screenshots/logout-functionality-back-button-blocked.png' });
    });
  });
});
